import json
with open('/app/resources/treasury_bulletin_1950_01.json', 'r') as f:
    data = json.load(f)

# Search for any price index related data
def search(obj, path=''):
    if isinstance(obj, dict):
        for k, v in obj.items():
            search(v, f'{path}.{k}')
    elif isinstance(obj, list):
        for i, v in enumerate(obj):
            search(v, f'{path}[{i}]')
    else:
        if isinstance(obj, str) and ('price' in obj.lower() or 'cpi' in obj.lower() or 'index' in obj.lower()):
            print(f'{path}: {obj}')

search(data)
